const fs = require("fs");
const lines = fs.readFileSync("/reference/glossary.jsonl", "utf8").split("\n").filter(Boolean);
const symbols = [
  "acknowledge", "activity", "apologize", "ask", "attitude", "character",
  "constraint_budget_limited", "dialogue", "duration", "entity_drinks",
  "failure", "gender_women", "occurred", "occurred_recently", "platform_label",
  "propose", "respond", "restaurant", "role_agent", "role_friend", "role_user",
  "statement", "style_academic", "style_catchy", "target", "tone_silly",
  "topic_pickup_lines", "unit_week", "user_practice", "wine"
];
for (const line of lines) {
  const obj = JSON.parse(line);
  if (symbols.includes(obj.id) || symbols.includes(obj.symbol)) {
    console.log("===", obj.id, "===");
    console.log(JSON.stringify(obj, null, 2));
  }
}
'

